import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are "Jessie", the AI Farm Assistant for Jessica Farms in Norton, Ohio. 
You are friendly, knowledgeable about local Ohio agriculture, and have a rustic, farmhouse personality.
You help visitors learn about:
- Fresh eggs (pasture-raised chickens)
- Raw local honey (wildflower)
- Seasonal produce available in Summit County
- Farm visits and community events
- General gardening tips for Ohio zone 6b

Keep your answers warm, helpful, and concise. Use occasional farm-themed emojis like 🌾, 🚜, 🍯, 🥚.
`;

export const getFarmAssistantResponse = async (userMessage: string, history: { role: 'user' | 'model', parts: [{ text: string }] }[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history,
        { role: 'user', parts: [{ text: userMessage }] }
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
        topP: 0.95,
        topK: 40,
      }
    });

    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Oops! It seems the tractor hit a snag. Let me try again in a bit! 🚜";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { getFarmAssistantResponse } from '../services/geminiService';
import { ChatMessage } from '../types';

const FarmChat: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'assistant', content: "Howdy! I'm Jessie. Got questions about the farm or what's in season? 🌾" }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsLoading(true);

    const history = messages.map(m => ({
      role: m.role === 'assistant' ? 'model' : 'user' as const,
      parts: [{ text: m.content }]
    }));

    const response = await getFarmAssistantResponse(userMsg, history);
    setMessages(prev => [...prev, { role: 'assistant', content: response || "Something went wrong!" }]);
    setIsLoading(false);
  };

  return (
    <div className="fixed bottom-6 right-6 z-50">
      {isOpen ? (
        <div className="w-80 md:w-96 h-[500px] bg-white clean-border flex flex-col overflow-hidden animate-in slide-in-from-bottom-5">
          {/* Header */}
          <div className="bg-forest p-4 text-cream flex justify-between items-center">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-full bg-honey flex items-center justify-center text-lg">👩‍🌾</div>
              <div>
                <h3 className="font-bold text-sm">Jessie</h3>
                <p className="text-[10px] opacity-80">Jessica Farms Assistant</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:text-honey transition-colors">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-cream/50">
            {messages.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-3 text-sm ${
                  msg.role === 'user' 
                    ? 'bg-forest text-white rounded-l-lg rounded-tr-lg' 
                    : 'bg-white border-2 border-forest/10 rounded-r-lg rounded-tl-lg text-forest'
                }`}>
                  {msg.content}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border-2 border-forest/10 rounded-r-lg rounded-tl-lg p-3">
                  <div className="flex gap-1">
                    <div className="w-2 h-2 bg-honey rounded-full animate-bounce"></div>
                    <div className="w-2 h-2 bg-honey rounded-full animate-bounce [animation-delay:-.3s]"></div>
                    <div className="w-2 h-2 bg-honey rounded-full animate-bounce [animation-delay:-.5s]"></div>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input */}
          <form onSubmit={handleSubmit} className="p-4 bg-white border-t-2 border-forest/10 flex gap-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Ask a question..."
              className="flex-1 text-sm border-2 border-forest/20 rounded-lg px-3 py-2 focus:border-honey outline-none transition-colors"
            />
            <button type="submit" className="bg-honey p-2 rounded-lg text-white hover:bg-honey/80 transition-colors">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
              </svg>
            </button>
          </form>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-honey text-white p-4 rounded-full shadow-lg border-2 border-forest flex items-center gap-2 hover:scale-110 transition-transform active:scale-95 group"
        >
          <span className="font-bold hidden group-hover:inline transition-all animate-in fade-in slide-in-from-right-2">Ask Jessie</span>
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
          </svg>
        </button>
      )}
    </div>
  );
};

export default FarmChat;

