import React, { useState, useEffect, useCallback, useRef } from 'react';

// --- SHARED UI COMPONENTS ---
const GameCard: React.FC<{ 
  title: string; 
  emoji: string; 
  color: string; 
  children: React.ReactNode;
  instructions: string;
}> = ({ title, emoji, color, children, instructions }) => (
  <div className={`relative bg-white rounded-[3rem] overflow-hidden border-2 border-stone-100 shadow-xl transition-all hover:shadow-2xl flex flex-col h-[500px] group`}>
    <div className={`p-6 ${color} text-white flex justify-between items-center border-b-4 border-black/10`}>
      <div className="flex items-center gap-3">
        <span className="text-3xl filter drop-shadow-md">{emoji}</span>
        <h3 className="font-black uppercase tracking-tighter text-xl italic">{title}</h3>
      </div>
      <div className="text-[10px] font-black uppercase tracking-widest opacity-80 px-3 py-1 bg-black/10 rounded-full">
        Interactive
      </div>
    </div>
    <div className="relative flex-grow overflow-hidden bg-stone-50">
      {children}
    </div>
    <div className="p-4 bg-white border-t border-stone-100">
      <p className="text-center text-[10px] font-black uppercase tracking-widest text-stone-400 italic">
        {instructions}
      </p>
    </div>
  </div>
);

// --- 1. HONEY HARVEST REIMAGINED ---
const BeeHarvestGame: React.FC = () => {
  const [score, setScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState(20);
  const [gameActive, setGameActive] = useState(false);
  const [bees, setBees] = useState<{ id: number; x: number; y: number; type: 'gold' | 'normal' }[]>([]);
  const [clickEffects, setClickEffects] = useState<{ id: number; x: number; y: number; val: string }[]>([]);

  const spawnBee = useCallback(() => {
    const isGold = Math.random() > 0.85;
    const newBee = {
      id: Date.now(),
      x: Math.random() * 80 + 10,
      y: Math.random() * 80 + 10,
      type: isGold ? 'gold' : 'normal' as const
    };
    setBees(prev => [...prev, newBee]);
    setTimeout(() => {
      setBees(prev => prev.filter(b => b.id !== newBee.id));
    }, 1200);
  }, []);

  const handleBeeClick = (bee: typeof bees[0]) => {
    const points = bee.type === 'gold' ? 50 : 10;
    setScore(s => s + points);
    setClickEffects(prev => [...prev, { id: Date.now(), x: bee.x, y: bee.y, val: `+${points}` }]);
    setBees(prev => prev.filter(b => b.id !== bee.id));
    setTimeout(() => setClickEffects(prev => prev.slice(1)), 800);
  };

  useEffect(() => {
    let timer: any;
    let spawnInterval: any;
    if (gameActive && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft(t => t - 1), 1000);
      spawnInterval = setInterval(spawnBee, 600);
    } else if (timeLeft === 0) {
      setGameActive(false);
      setBees([]);
    }
    return () => {
      clearInterval(timer);
      clearInterval(spawnInterval);
    };
  }, [gameActive, timeLeft, spawnBee]);

  return (
    <GameCard title="Honey Rush" emoji="🍯" color="bg-amber-500" instructions="Tap the bees! Golden bees are worth 5x.">
      <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/pollen.png')] opacity-10"></div>

      {!gameActive ? (
        <div className="h-full flex flex-col items-center justify-center p-10 text-center space-y-6">
          <div className="text-6xl animate-bounce">🌻</div>
          <div className="space-y-2">
            <h4 className="text-3xl font-black text-amber-900 italic">Spring is Here!</h4>
            <p className="text-amber-800/60 font-medium italic">Collect as much nectar as you can before the sun sets.</p>
          </div>
          <button 
            onClick={() => {setScore(0); setTimeLeft(20); setGameActive(true);}} 
            className="bg-amber-900 text-white px-10 py-4 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            {timeLeft === 0 ? 'Try Again' : 'Start Harvest'}
          </button>
          {timeLeft === 0 && score > 0 && <div className="text-amber-900 font-black text-xl">Best Run: {score} Nectar</div>}
        </div>
      ) : (
        <div className="h-full relative overflow-hidden">
          {/* Meadow Background */}
          <div className="absolute inset-0 flex flex-wrap gap-12 p-8 opacity-20 pointer-events-none">
            {Array.from({length: 12}).map((_, i) => (
              <span key={i} className={`text-4xl animate-pulse delay-${i*100}`}>🌸</span>
            ))}
          </div>

          <div className="absolute top-4 left-6 flex flex-col">
            <span className="text-[10px] font-black uppercase text-amber-900/40">Sunlight Left</span>
            <span className="text-2xl font-black text-amber-900">{timeLeft}s</span>
          </div>
          <div className="absolute top-4 right-6 text-right">
            <span className="text-[10px] font-black uppercase text-amber-900/40">Total Nectar</span>
            <span className="text-2xl font-black text-amber-900">{score}</span>
          </div>

          {bees.map(bee => (
            <button 
              key={bee.id} 
              onClick={() => handleBeeClick(bee)}
              className={`absolute text-5xl select-none cursor-pointer transform hover:scale-110 active:scale-90 transition-all duration-300 animate-in zoom-in-50
              ${bee.type === 'gold' ? 'filter drop-shadow-[0_0_15px_rgba(255,215,0,0.8)] scale-125' : ''}`}
              style={{ left: `${bee.x}%`, top: `${bee.y}%`, transition: 'all 1s cubic-bezier(0.34, 1.56, 0.64, 1)' }}
            >
              {bee.type === 'gold' ? '🐝✨' : '🐝'}
            </button>
          ))}

          {clickEffects.map(eff => (
            <div 
              key={eff.id}
              className="absolute font-black text-amber-600 animate-out fade-out slide-out-to-top-10 pointer-events-none"
              style={{ left: `${eff.x}%`, top: `${eff.y}%` }}
            >
              {eff.val}
            </div>
          ))}
        </div>
      )}
    </GameCard>
  );
};

// --- 2. KOI SANCTUARY REIMAGINED ---
const KoiPondGame: React.FC = () => {
  const [fishes, setFishes] = useState<{ id: number; x: number; y: number; color: string; deg: number; size: number }[]>([]);
  const [ripples, setRipples] = useState<{ id: number; x: number; y: number }[]>([]);
  const [food, setFood] = useState<{ id: number; x: number; y: number }[]>([]);
  const [gameActive, setGameActive] = useState(false);
  const [level, setLevel] = useState(1);

  useEffect(() => {
    const initialFishes = Array.from({ length: 6 }).map((_, i) => ({
      id: i,
      x: Math.random() * 90,
      y: Math.random() * 90,
      color: ['#ff4d4d', '#ffcc00', '#ffffff', '#333333', '#fb8500'][Math.floor(Math.random() * 5)],
      deg: Math.random() * 360,
      size: 0.8 + Math.random() * 0.5
    }));
    setFishes(initialFishes);
  }, []);

  useEffect(() => {
    if (!gameActive) return;
    const interval = setInterval(() => {
      setFishes(prev => prev.map(f => {
        let newX = f.x;
        let newY = f.y;
        let newDeg = f.deg;

        if (food.length > 0) {
          const nearest = food[0];
          const dx = nearest.x - f.x;
          const dy = nearest.y - f.y;
          const targetDeg = Math.atan2(dy, dx) * (180 / Math.PI);

          // Smooth rotation
          const diff = ((targetDeg - f.deg + 540) % 360) - 180;
          newDeg += diff * 0.1;

          newX += Math.cos(newDeg * Math.PI / 180) * 1.8;
          newY += Math.sin(newDeg * Math.PI / 180) * 1.8;

          if (Math.abs(dx) < 4 && Math.abs(dy) < 4) {
            setFood(currFood => currFood.filter(p => p.id !== nearest.id));
            setLevel(l => l + 0.1); // Subtle progression
          }
        } else {
          // Wander behavior
          newDeg += (Math.random() - 0.5) * 5;
          newX += Math.cos(newDeg * Math.PI / 180) * 0.7;
          newY += Math.sin(newDeg * Math.PI / 180) * 0.7;

          if (newX < 5 || newX > 90 || newY < 5 || newY > 90) newDeg = (f.deg + 160) % 360;
        }

        return { ...f, x: newX, y: newY, deg: newDeg };
      }));
    }, 40);

    return () => clearInterval(interval);
  }, [food, gameActive]);

  const handleClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!gameActive) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    setFood(prev => [...prev.slice(-4), { id: Date.now(), x, y }]);
    setRipples(prev => [...prev, { id: Date.now(), x, y }]);
    setTimeout(() => setRipples(prev => prev.slice(1)), 2000);
  };

  return (
    <GameCard title="Koi Sanctuary" emoji="🎏" color="bg-blue-600" instructions="Tap the water to drop pellets. Watch them gather!">
      <div className="absolute inset-0 bg-blue-900/10"></div>

      {!gameActive ? (
        <div className="h-full flex flex-col items-center justify-center p-10 text-center space-y-6">
          <div className="text-6xl animate-pulse">🎐</div>
          <div className="space-y-2">
            <h4 className="text-3xl font-black text-blue-900 italic">Peaceful Pond</h4>
            <p className="text-blue-800/60 font-medium italic">Feed the koi to grow the sanctuary. Quiet moments from Norton.</p>
          </div>
          <button 
            onClick={() => setGameActive(true)} 
            className="bg-blue-900 text-white px-10 py-4 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            Enter Pond
          </button>
        </div>
      ) : (
        <div 
          onClick={handleClick}
          className="h-full relative overflow-hidden cursor-crosshair bg-gradient-to-b from-blue-400/20 to-blue-600/30"
        >
          {/* Water Ripples */}
          {ripples.map(r => (
            <div 
              key={r.id}
              className="absolute border border-white/40 rounded-full animate-ping pointer-events-none"
              style={{ 
                left: `${r.x}%`, 
                top: `${r.y}%`, 
                width: '100px', 
                height: '100px', 
                marginLeft: '-50px', 
                marginTop: '-50px',
                animationDuration: '2s'
              }}
            />
          ))}

          {/* Food Pellets */}
          {food.map(p => (
            <div key={p.id} className="absolute w-3 h-3 bg-amber-900 rounded-full shadow-lg z-10" style={{ left: `${p.x}%`, top: `${p.y}%` }} />
          ))}

          {/* Koi Fishes */}
          {fishes.map(f => (
            <div 
              key={f.id} 
              className="absolute transition-all duration-100 ease-linear pointer-events-none drop-shadow-lg"
              style={{ 
                left: `${f.x}%`, 
                top: `${f.y}%`, 
                transform: `translate(-50%, -50%) rotate(${f.deg}deg) scale(${f.size})`,
                color: f.color,
                fontSize: '2.5rem'
              }}
            >
              <div className="flex items-center gap-1">
                 <span>🐟</span>
                 <div className="w-1 h-2 bg-white/20 rounded-full animate-pulse"></div>
              </div>
            </div>
          ))}

          <div className="absolute bottom-6 left-6 bg-white/40 backdrop-blur-md px-4 py-2 rounded-full border border-white/20 text-[10px] font-black uppercase tracking-widest text-blue-900">
             Sanctuary Level: {level.toFixed(1)}
          </div>
        </div>
      )}
    </GameCard>
  );
};

