const ButterbeanKitchenGame: React.FC = () => {
  const [score, setScore] = useState(0);
  const [items, setItems] = useState<{ id: number; x: number; y: number; type: 'milk' | 'bean' | 'pot'; rotation: number }[]>([]);
  const [catX, setCatX] = useState(50);
  const [isPouncing, setIsPouncing] = useState(false);
  const [gameActive, setGameActive] = useState(false);
  const [streak, setStreak] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!gameActive) return;
    const interval = setInterval(() => {
      setItems(prev => [
        ...prev.map(item => ({ ...item, y: item.y + (2.5 + score * 0.05), rotation: item.rotation + 5 })).filter(item => item.y < 105),
        ...(Math.random() > 0.92 ? [{ 
          id: Date.now(), 
          x: Math.random() * 85 + 5, 
          y: -10, 
          type: Math.random() > 0.25 ? (Math.random() > 0.5 ? 'milk' : 'bean') : 'pot',
          rotation: Math.random() * 360
        }] as const : [])
      ]);
    }, 40);
    return () => clearInterval(interval);
  }, [gameActive, score]);

  useEffect(() => {
    if (!gameActive) return;
    items.forEach(item => {
      if (item.y > 82 && item.y < 95 && Math.abs(item.x - catX) < 12) {
        if (item.type === 'pot') {
          setGameActive(false);
          setStreak(0);
        } else {
          setScore(s => s + 1);
          setStreak(st => st + 1);
          setIsPouncing(true);
          setTimeout(() => setIsPouncing(false), 150);
          setItems(prev => prev.filter(i => i.id !== item.id));
        }
      }
    });
  }, [items, catX, gameActive]);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 100;
      setCatX(Math.max(8, Math.min(92, x)));
    }
  };

  return (
    <GameCard title="Kitchen Pounce" emoji="🍳" color="bg-orange-500" instructions="Move the mouse to catch ingredients. Avoid the hot pots!">
      {!gameActive ? (
        <div className="h-full flex flex-col items-center justify-center p-10 text-center space-y-6">
