            <p className="text-orange-800/60 font-medium italic">Help Butterbean catch the harvest ingredients. Don't touch the stove!</p>
          </div>
          <button 
            onClick={() => {setScore(0); setItems([]); setGameActive(true);}} 
            className="bg-orange-900 text-white px-10 py-4 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            Start Pouncing
          </button>
          {score > 0 && <div className="text-orange-900 font-black text-xl">Last Score: {score}</div>}
        </div>
      ) : (
        <div 
          ref={containerRef}
          onMouseMove={handleMouseMove}
          className="h-full relative overflow-hidden cursor-none bg-[url('https://www.transparenttextures.com/patterns/wood-pattern.png')] bg-orange-50/50"
        >
          <div className="absolute top-4 right-6 flex flex-col items-end">
             <span className="text-[10px] font-black uppercase text-orange-900/40">Caught</span>
             <span className="text-2xl font-black text-orange-900">{score}</span>
             {streak > 5 && <span className="text-[8px] font-black bg-orange-600 text-white px-2 py-0.5 rounded-full animate-bounce">Streak!</span>}
          </div>

          {items.map(item => (
            <div 
              key={item.id} 
              className="absolute text-4xl filter drop-shadow-md" 
              style={{ 
                left: `${item.x}%`, 
                top: `${item.y}%`, 
                transform: `rotate(${item.rotation}deg)`,
                transition: 'top 0.04s linear'
              }}
            >
              {item.type === 'milk' ? '🥛' : item.type === 'bean' ? '🫘' : '🔥'}
            </div>
          ))}

          <div 
            className={`absolute bottom-6 text-6xl transition-transform duration-75 pointer-events-none 
              ${isPouncing ? 'scale-125 -translate-y-4' : 'scale-100'}`}
            style={{ left: `${catX}%`, transform: `translateX(-50%) ${isPouncing ? 'scale(1.2) translateY(-20px)' : ''}` }}
          >
            🐈
          </div>

          <div className="absolute bottom-0 w-full h-4 bg-orange-900/10"></div>
        </div>
      )}
    </GameCard>
  );
};

