            onClick={() => {setScore(0); setTimeLeft(20); setGameActive(true);}} 
            className="bg-amber-900 text-white px-10 py-4 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            {timeLeft === 0 ? 'Try Again' : 'Start Harvest'}
          </button>
          {timeLeft === 0 && score > 0 && <div className="text-amber-900 font-black text-xl">Best Run: {score} Nectar</div>}
        </div>
      ) : (
        <div className="h-full relative overflow-hidden">
          {/* Meadow Background */}
          <div className="absolute inset-0 flex flex-wrap gap-12 p-8 opacity-20 pointer-events-none">
            {Array.from({length: 12}).map((_, i) => (
              <span key={i} className={`text-4xl animate-pulse delay-${i*100}`}>🌸</span>
            ))}
