              ${bee.type === 'gold' ? 'filter drop-shadow-[0_0_15px_rgba(255,215,0,0.8)] scale-125' : ''}`}
              style={{ left: `${bee.x}%`, top: `${bee.y}%`, transition: 'all 1s cubic-bezier(0.34, 1.56, 0.64, 1)' }}
            >
              {bee.type === 'gold' ? '🐝✨' : '🐝'}
            </button>
          ))}

          {clickEffects.map(eff => (
            <div 
              key={eff.id}
              className="absolute font-black text-amber-600 animate-out fade-out slide-out-to-top-10 pointer-events-none"
              style={{ left: `${eff.x}%`, top: `${eff.y}%` }}
            >
              {eff.val}
            </div>
          ))}
        </div>
      )}
    </GameCard>
  );
