  const [streak, setStreak] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!gameActive) return;
    const interval = setInterval(() => {
      setItems(prev => [
        ...prev.map(item => ({ ...item, y: item.y + (2.5 + score * 0.05), rotation: item.rotation + 5 })).filter(item => item.y < 105),
        ...(Math.random() > 0.92 ? [{ 
