            className="bg-amber-900 text-white px-12 py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            {timeLeft === 0 ? 'Restart Harvest' : 'Start Game'}
          </button>
          {timeLeft === 0 && score > 0 && <div className="text-amber-900 font-black text-2xl">Total Harvest: {score}</div>}
        </div>
      ) : (
        <div className="h-full relative overflow-hidden bg-amber-50/30">
          <div className="absolute top-8 left-10 flex flex-col">
            <span className="text-[12px] font-black uppercase text-amber-900/40 tracking-widest">Time Remaining</span>
            <span className="text-4xl font-black text-amber-900">{timeLeft}s</span>
          </div>
          <div className="absolute top-8 right-10 text-right">
