import React, { useState, useEffect, useCallback, useRef } from 'react';

// --- SHARED UI COMPONENTS ---
const GameCard: React.FC<{ 
  title: string; 
  emoji: string; 
  color: string; 
  children: React.ReactNode;
  instructions: string;
  gameActive: boolean;
  onExit?: () => void;
  onStart?: () => void;
}> = ({ title, emoji, color, children, instructions, gameActive, onExit, onStart }) => {

  useEffect(() => {
    const handleGlobalKeys = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && gameActive) onExit?.();
      if (e.key === ' ' && !gameActive) {
        e.preventDefault();
        onStart?.();
      }
    };
    window.addEventListener('keydown', handleGlobalKeys);
    return () => window.removeEventListener('keydown', handleGlobalKeys);
  }, [gameActive, onExit, onStart]);

  const activeClasses = gameActive 
    ? "fixed inset-0 z-[100] w-screen h-screen rounded-0" 
    : "relative w-full h-[500px] rounded-[3rem] overflow-hidden border-2 border-stone-100 shadow-xl";

  return (
    <div className={`${activeClasses} bg-white transition-all duration-500 flex flex-col group`}>
      <div className={`p-6 ${color} text-white flex justify-between items-center border-b-4 border-black/10`}>
        <div className="flex items-center gap-3">
          <span className="text-3xl filter drop-shadow-md">{emoji}</span>
          <h3 className="font-black uppercase tracking-tighter text-xl italic">{title}</h3>
        </div>
        {gameActive ? (
          <button 
            onClick={onExit}
            className="bg-black/20 hover:bg-black/40 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-colors"
          >
            Esc / Exit Game ✕
          </button>
        ) : (
          <div className="text-[10px] font-black uppercase tracking-widest opacity-80 px-3 py-1 bg-black/10 rounded-full">
            Ready to Play
          </div>
        )}
      </div>
      <div className="relative flex-grow overflow-hidden bg-stone-50">
        {children}
      </div>
      {!gameActive && (
        <div className="p-4 bg-white border-t border-stone-100">
          <p className="text-center text-[10px] font-black uppercase tracking-widest text-stone-400 italic">
            {instructions}
          </p>
        </div>
      )}
    </div>
  );
};

// --- 1. HONEY RUSH ---
const BeeHarvestGame: React.FC = () => {
  const [score, setScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState(20);
  const [gameActive, setGameActive] = useState(false);
  const [bees, setBees] = useState<{ id: number; x: number; y: number; type: 'gold' | 'normal' }[]>([]);
  const [clickEffects, setClickEffects] = useState<{ id: number; x: number; y: number; val: string }[]>([]);

  const startGame = () => {
    setScore(0);
    setTimeLeft(20);
    setBees([]);
    setClickEffects([]);
    setGameActive(true);
  };

  const spawnBee = useCallback(() => {
    const isGold = Math.random() > 0.85;
    const newBee: { id: number; x: number; y: number; type: 'gold' | 'normal' } = {
      id: Date.now() + Math.random(),
      x: Math.random() * 80 + 10,
      y: Math.random() * 80 + 10,
      type: isGold ? 'gold' : 'normal'
    };
    setBees(prev => [...prev, newBee]);
    setTimeout(() => {
      setBees(prev => prev.filter(b => b.id !== newBee.id));
    }, 1500);
  }, []);

  const handleBeeClick = (bee: typeof bees[0]) => {
    const points = bee.type === 'gold' ? 50 : 10;
    setScore(s => s + points);
    setClickEffects(prev => [...prev, { id: Date.now(), x: bee.x, y: bee.y, val: `+${points}` }]);
    setBees(prev => prev.filter(b => b.id !== bee.id));
    setTimeout(() => setClickEffects(prev => prev.slice(1)), 800);
  };

  useEffect(() => {
    let timer: any;
    let spawnInterval: any;
    if (gameActive && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft(t => t - 1), 1000);
      spawnInterval = setInterval(spawnBee, 700);
    } else if (timeLeft <= 0) {
      setGameActive(false);
    }
    return () => {
      clearInterval(timer);
      clearInterval(spawnInterval);
    };
  }, [gameActive, timeLeft, spawnBee]);

  return (
    <GameCard 
      title="Honey Rush" 
      emoji="🍯" 
      color="bg-amber-500" 
      instructions="Tap the bees! Spacebar to start."
      gameActive={gameActive}
      onExit={() => setGameActive(false)}
      onStart={startGame}
    >
      <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/pollen.png')] opacity-10"></div>

      {!gameActive ? (
        <div className="h-full flex flex-col items-center justify-center p-10 text-center space-y-6">
          <div className="text-8xl animate-bounce">🌻</div>
          <div className="space-y-2">
            <h4 className="text-4xl font-black text-amber-900 italic">Spring Harvest</h4>
            <p className="text-amber-800/60 font-medium italic">Collect nectar before the clock runs out.</p>
          </div>
          <button 
            onClick={startGame} 
            className="bg-amber-900 text-white px-12 py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            {timeLeft <= 0 ? 'Restart Harvest' : 'Start Game'}
          </button>
          {timeLeft <= 0 && score > 0 && <div className="text-amber-900 font-black text-2xl">Total Harvest: {score}</div>}
        </div>
      ) : (
        <div className="h-full relative overflow-hidden bg-amber-50/30">
          <div className="absolute top-8 left-10 flex flex-col z-10">
            <span className="text-[12px] font-black uppercase text-amber-900/40 tracking-widest">Time Remaining</span>
            <span className="text-4xl font-black text-amber-900">{timeLeft}s</span>
          </div>
          <div className="absolute top-8 right-10 text-right z-10">
            <span className="text-[12px] font-black uppercase text-amber-900/40 tracking-widest">Nectar Points</span>
            <span className="text-4xl font-black text-amber-900">{score}</span>
          </div>

          {bees.map(bee => (
            <button 
              key={bee.id} 
              onClick={(e) => { e.stopPropagation(); handleBeeClick(bee); }}
              className={`absolute text-7xl select-none cursor-pointer transform hover:scale-110 active:scale-90 transition-all duration-300 animate-in zoom-in-50
              ${bee.type === 'gold' ? 'filter drop-shadow-[0_0_20px_rgba(255,215,0,0.8)] scale-125' : ''}`}
              style={{ left: `${bee.x}%`, top: `${bee.y}%`, transform: 'translate(-50%, -50%)' }}
            >
              {bee.type === 'gold' ? '🐝✨' : '🐝'}
            </button>
          ))}

          {clickEffects.map(eff => (
            <div 
              key={eff.id}
              className="absolute font-black text-amber-600 text-2xl animate-out fade-out slide-out-to-top-10 pointer-events-none"
              style={{ left: `${eff.x}%`, top: `${eff.y}%` }}
            >
              {eff.val}
            </div>
          ))}
        </div>
      )}
    </GameCard>
  );
};

// --- 2. KOI POND ---
const KoiPondGame: React.FC = () => {
  const [fishes, setFishes] = useState<{ id: number; x: number; y: number; color: string; deg: number; size: number }[]>([]);
  const [ripples, setRipples] = useState<{ id: number; x: number; y: number }[]>([]);
  const [food, setFood] = useState<{ id: number; x: number; y: number }[]>([]);
  const [gameActive, setGameActive] = useState(false);
  const [level, setLevel] = useState(1);

  const startGame = () => {
    setLevel(1);
    setFood([]);
    setRipples([]);
    setGameActive(true);
  };

  useEffect(() => {
    const initialFishes = Array.from({ length: 8 }).map((_, i) => ({
      id: i,
      x: Math.random() * 90,
      y: Math.random() * 90,
      color: ['#ff4d4d', '#ffcc00', '#ffffff', '#333333', '#fb8500'][Math.floor(Math.random() * 5)],
      deg: Math.random() * 360,
      size: 0.8 + Math.random() * 0.7
    }));
    setFishes(initialFishes);
  }, []);

  useEffect(() => {
    if (!gameActive) return;
    const interval = setInterval(() => {
      setFishes(prev => prev.map(f => {
        let newX = f.x;
        let newY = f.y;
        let newDeg = f.deg;

        if (food.length > 0) {
          const nearest = food[0];
          const dx = nearest.x - f.x;
          const dy = nearest.y - f.y;
          const targetDeg = Math.atan2(dy, dx) * (180 / Math.PI);

          const diff = ((targetDeg - f.deg + 540) % 360) - 180;
          newDeg += diff * 0.1;
          newX += Math.cos(newDeg * Math.PI / 180) * 1.5;
          newY += Math.sin(newDeg * Math.PI / 180) * 1.5;

          if (Math.abs(dx) < 3 && Math.abs(dy) < 3) {
            setFood(currFood => currFood.filter(p => p.id !== nearest.id));
            setLevel(l => l + 0.1);
          }
        } else {
          newDeg += (Math.random() - 0.5) * 8;
          newX += Math.cos(newDeg * Math.PI / 180) * 0.8;
          newY += Math.sin(newDeg * Math.PI / 180) * 0.8;
          if (newX < 5 || newX > 95 || newY < 5 || newY > 95) newDeg = (f.deg + 160) % 360;
        }

        return { ...f, x: newX, y: newY, deg: newDeg };
      }));
    }, 40);
    return () => clearInterval(interval);
  }, [food, gameActive]);

  const handleClick = (e: React.MouseEvent<HTMLDivElement> | React.TouchEvent<HTMLDivElement>) => {
    if (!gameActive) return;
    const container = e.currentTarget.getBoundingClientRect();
    let clientX, clientY;

    if ('touches' in e) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = e.clientX;
      clientY = e.clientY;
    }

    const x = ((clientX - container.left) / container.width) * 100;
    const y = ((clientY - container.top) / container.height) * 100;

    setFood(prev => [...prev.slice(-6), { id: Date.now(), x, y }]);
    setRipples(prev => [...prev, { id: Date.now(), x, y }]);
    setTimeout(() => setRipples(prev => prev.slice(1)), 2000);
  };

  return (
    <GameCard 
      title="Koi Pond" 
      emoji="🎏" 
      color="bg-blue-600" 
      instructions="Tap/Click to feed the koi. Spacebar to start."
      gameActive={gameActive}
      onExit={() => setGameActive(false)}
      onStart={startGame}
    >
      <div className="absolute inset-0 bg-blue-900/5"></div>

      {!gameActive ? (
        <div className="h-full flex flex-col items-center justify-center p-10 text-center space-y-6">
          <div className="text-8xl animate-pulse">🎐</div>
          <div className="space-y-2">
            <h4 className="text-4xl font-black text-blue-900 italic">Peaceful Pond</h4>
            <p className="text-blue-800/60 font-medium italic">Enter the sanctuary of Norton. Relax and feed the koi.</p>
          </div>
          <button 
            onClick={startGame} 
            className="bg-blue-900 text-white px-12 py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            Start Game
          </button>
        </div>
      ) : (
        <div 
          onClick={handleClick}
          onTouchStart={handleClick}
          className="h-full relative overflow-hidden cursor-crosshair bg-gradient-to-b from-blue-300/20 to-blue-500/30"
        >
          {ripples.map(r => (
            <div 
              key={r.id}
              className="absolute border-2 border-white/50 rounded-full animate-ping pointer-events-none"
              style={{ left: `${r.x}%`, top: `${r.y}%`, width: '150px', height: '150px', marginLeft: '-75px', marginTop: '-75px' }}
            />
          ))}

          {food.map(p => (
            <div key={p.id} className="absolute w-4 h-4 bg-amber-800 rounded-full shadow-lg z-10" style={{ left: `${p.x}%`, top: `${p.y}%` }} />
          ))}

          {fishes.map(f => (
            <div 
              key={f.id} 
              className="absolute transition-all duration-100 ease-linear pointer-events-none drop-shadow-2xl"
              style={{ 
                left: `${f.x}%`, 
                top: `${f.y}%`, 
                transform: `translate(-50%, -50%) rotate(${f.deg}deg) scale(${f.size})`,
                color: f.color,
                fontSize: '4rem'
              }}
            >
               🐟
            </div>
          ))}

          <div className="absolute bottom-10 left-10 bg-white/60 backdrop-blur-md px-8 py-4 rounded-full border border-white/40 text-sm font-black uppercase tracking-[0.2em] text-blue-900 shadow-xl">
             Growth Progress: {level.toFixed(1)}
          </div>
        </div>
      )}
    </GameCard>
  );
};

// --- 3. KITCHEN POUNCE ---
const ButterbeanKitchenGame: React.FC = () => {
  const [score, setScore] = useState(0);
  const [items, setItems] = useState<{ id: number; x: number; y: number; type: 'milk' | 'bean' | 'pot'; rotation: number }[]>([]);
  const [catX, setCatX] = useState(50);
  const [isPouncing, setIsPouncing] = useState(false);
  const [gameActive, setGameActive] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const startGame = () => {
    setScore(0);
    setItems([]);
    setCatX(50);
    setGameActive(true);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!gameActive) return;
      if (e.key === 'ArrowLeft') setCatX(x => Math.max(8, x - 8));
      if (e.key === 'ArrowRight') setCatX(x => Math.min(92, x + 8));
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameActive]);

  useEffect(() => {
    if (!gameActive) return;
    const interval = setInterval(() => {
      setItems(prev => [
        ...prev.map(item => ({ ...item, y: item.y + (1.8 + score * 0.03), rotation: item.rotation + 5 })).filter(item => item.y < 110),
        ...(Math.random() > 0.92 ? [{ 
          id: Date.now() + Math.random(), 
          x: Math.random() * 85 + 7, 
          y: -10, 
          type: Math.random() > 0.2 ? (Math.random() > 0.5 ? 'milk' : 'bean') : 'pot',
          rotation: Math.random() * 360
        }] as const : [])
      ]);
    }, 40);
    return () => clearInterval(interval);
  }, [gameActive, score]);

  useEffect(() => {
    if (!gameActive) return;
    items.forEach(item => {
      if (item.y > 80 && item.y < 95 && Math.abs(item.x - catX) < 10) {
        if (item.type === 'pot') {
          setGameActive(false);
        } else {
          setScore(s => s + 1);
          setIsPouncing(true);
          setTimeout(() => setIsPouncing(false), 200);
          setItems(prev => prev.filter(i => i.id !== item.id));
        }
      }
    });
  }, [items, catX, gameActive]);

  const handlePointerMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!gameActive || !containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    let clientX;
    if ('touches' in e) {
      clientX = e.touches[0].clientX;
    } else {
      clientX = e.clientX;
    }
    const x = ((clientX - rect.left) / rect.width) * 100;
    setCatX(Math.max(8, Math.min(92, x)));
  };

  return (
    <GameCard 
      title="Kitchen Pounce" 
      emoji="🍳" 
      color="bg-orange-500" 
      instructions="Arrows or Move Mouse. Spacebar to start."
      gameActive={gameActive}
      onExit={() => setGameActive(false)}
      onStart={startGame}
    >
      {!gameActive ? (
        <div className="h-full flex flex-col items-center justify-center p-10 text-center space-y-6">
          <div className="text-8xl">🐈</div>
          <div className="space-y-2">
            <h4 className="text-4xl font-black text-orange-900 italic">Chef Butterbean</h4>
            <p className="text-orange-800/60 font-medium italic">Catch ingredients, avoid the fire!</p>
          </div>
          <button 
            onClick={startGame} 
            className="bg-orange-900 text-white px-12 py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            Start Game
          </button>
          {score > 0 && <div className="text-orange-900 font-black text-3xl italic">Score: {score}</div>}
        </div>
      ) : (
        <div 
          ref={containerRef}
          onMouseMove={handlePointerMove}
          onTouchMove={handlePointerMove}
          className="h-full relative overflow-hidden bg-[url('https://www.transparenttextures.com/patterns/wood-pattern.png')] bg-orange-50/50"
        >
          <div className="absolute top-8 right-10 text-right">
             <span className="text-[12px] font-black uppercase text-orange-900/40 tracking-widest">Captured</span>
             <span className="text-4xl font-black text-orange-900 block">{score}</span>
          </div>

          {items.map(item => (
            <div 
              key={item.id} 
              className="absolute text-5xl filter drop-shadow-lg" 
              style={{ left: `${item.x}%`, top: `${item.y}%`, transform: `translate(-50%, -50%) rotate(${item.rotation}deg)` }}
            >
              {item.type === 'milk' ? '🥛' : item.type === 'bean' ? '🫘' : '🔥'}
            </div>
          ))}

          <div 
            className={`absolute bottom-10 text-6xl transition-all duration-75 pointer-events-none drop-shadow-xl
              ${isPouncing ? 'scale-125 -translate-y-8' : 'scale-100'}`}
            style={{ left: `${catX}%`, transform: 'translateX(-50%)' }}
          >
            🐈
          </div>
        </div>
      )}
    </GameCard>
  );
};

// --- 4. BERNIE'S DASH ---
const BernieSledGame: React.FC = () => {
  const [score, setScore] = useState(0);
  const [obstacles, setObstacles] = useState<{ id: number; x: number; y: number; type: 'bone' | 'tree' | 'ice' }[]>([]);
  const [huskyX, setHuskyX] = useState(50);
  const [gameActive, setGameActive] = useState(false);
  const [speed, setSpeed] = useState(2.5);

  const startGame = () => {
    setScore(0);
    setObstacles([]);
    setHuskyX(50);
    setSpeed(2.5);
    setGameActive(true);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!gameActive) return;
      if (e.key === 'ArrowLeft') setHuskyX(x => Math.max(12, x - 12));
      if (e.key === 'ArrowRight') setHuskyX(x => Math.min(88, x + 12));
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameActive]);

  useEffect(() => {
    if (!gameActive) return;
    const interval = setInterval(() => {
      setObstacles(prev => [
        ...prev.map(o => ({ ...o, y: o.y + speed })).filter(o => o.y < 110),
        ...(Math.random() > 0.90 ? [{ 
          id: Date.now() + Math.random(), 
          x: Math.random() * 80 + 10, 
          y: -10, 
          type: Math.random() > 0.3 ? (Math.random() > 0.1 ? 'tree' : 'ice') : 'bone' 
        }] as const : [])
      ]);
      setScore(s => s + 1);
      setSpeed(s => Math.min(10, 2.5 + score * 0.001));
    }, 40);
    return () => clearInterval(interval);
  }, [gameActive, score, speed]);

  useEffect(() => {
    if (!gameActive) return;
    obstacles.forEach(o => {
      if (o.y > 75 && o.y < 95 && Math.abs(o.x - huskyX) < 10) {
        if (o.type === 'tree') {
          setGameActive(false);
        } else if (o.type === 'bone') {
          setScore(s => s + 500);
          setObstacles(prev => prev.filter(obs => obs.id !== o.id));
        } else if (o.type === 'ice') {
           setHuskyX(x => x + (Math.random() > 0.5 ? 20 : -20));
        }
      }
    });
  }, [obstacles, huskyX, gameActive]);

  return (
    <GameCard 
      title="Bernie's Dash" 
      emoji="🛷" 
      color="bg-slate-700" 
      instructions="Arrow Keys / Tap left or right. Spacebar to start."
      gameActive={gameActive}
      onExit={() => setGameActive(false)}
      onStart={startGame}
    >
      {!gameActive ? (
        <div className="h-full flex flex-col items-center justify-center p-10 text-center space-y-6">
          <div className="text-8xl">🐺</div>
          <div className="space-y-2">
            <h4 className="text-4xl font-black text-slate-900 italic">Winter Run</h4>
            <p className="text-slate-700/60 font-medium italic">Dodge the trees in the Norton woods!</p>
          </div>
          <button 
            onClick={startGame} 
            className="bg-slate-900 text-white px-12 py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            Start Game
          </button>
          {score > 0 && <div className="text-slate-900 font-black text-3xl italic">Meters: {Math.floor(score/10)}m</div>}
        </div>
      ) : (
        <div className="h-full relative overflow-hidden bg-blue-50/50">
          <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/snow.png')] opacity-30 animate-[pulse_5s_infinite]"></div>

          <div className="absolute inset-0 flex z-20">
             <div className="w-1/2 h-full cursor-pointer" onClick={() => setHuskyX(Math.max(12, huskyX - 25))}></div>
             <div className="w-1/2 h-full cursor-pointer" onClick={() => setHuskyX(Math.min(88, huskyX + 25))}></div>
          </div>

          <div className="absolute top-8 left-10">
             <span className="text-[12px] font-black uppercase text-slate-900/40 tracking-widest">Sled Speed</span>
             <div className="flex gap-1 mt-2">
                {Array.from({length: Math.floor(speed * 1.5)}).map((_, i) => (
                  <div key={i} className="w-2 h-6 bg-blue-500 rounded-full"></div>
                ))}
             </div>
          </div>

          <div className="absolute top-8 right-10 text-right">
             <span className="text-[12px] font-black uppercase text-slate-900/40 tracking-widest">Distance Traveled</span>
             <span className="text-4xl font-black text-slate-900 block">{Math.floor(score/10)}m</span>
          </div>

          {obstacles.map(o => (
            <div 
              key={o.id} 
              className={`absolute text-6xl filter drop-shadow-xl`} 
              style={{ left: `${o.x}%`, top: `${o.y}%`, transform: 'translate(-50%, -50%)' }}
            >
              {o.type === 'bone' ? '🦴' : o.type === 'ice' ? '💎' : '🌲'}
            </div>
          ))}

          <div 
            className="absolute bottom-14 text-6xl transition-all duration-300 pointer-events-none drop-shadow-2xl z-10" 
            style={{ left: `${huskyX}%`, transform: 'translateX(-50%)' }}
          >
            🐺
          </div>
        </div>
      )}
    </GameCard>
  );
};

